pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint96 v0, uint96 v1, uint96 v2, uint96 threshold) public {
        // Token helper reverts transferFrom when the value reaches threshold;
        // the fuzzer chooses values so failure is possible but not forced.
        BadToken tok = new BadToken(uint256(threshold));
        address from = address(0xA11CE);
        address[] memory tos = new address[](3);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        tos[2] = address(0x3);
        uint[] memory vs = new uint[](3);
        vs[0] = uint256(v0);
        vs[1] = uint256(v1);
        vs[2] = uint256(v2);

        bool ok;
        try c.transfer(from, address(tok), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: transfer succeeds if and only if every transferFrom succeeds.
        bool allSucceed = uint256(v0) < uint256(threshold)
            && uint256(v1) < uint256(threshold)
            && uint256(v2) < uint256(threshold);
        assertTrue(ok == allSucceed);
    }
}

contract BadToken {
    uint256 public threshold;
    constructor(uint256 t) { threshold = t; }
    function transferFrom(address, address, uint256 value) external returns (bool) {
        if (value >= threshold) revert();
        return true;
    }
}
