contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function check(address from, address to, uint v) public returns (bool) {
		address[] memory tos = new address[](1);
		tos[0] = to;
		uint[] memory vs = new uint[](1);
		vs[0] = v;
		// address(this) has no receive/fallback, so any external call with data reverts
		(bool r, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(this), tos, vs));
		assert(!r);
		return r;
	}
}

contract InvMutTest {
	C c;
	uint public calls;

	constructor(C _c) { c = _c; }

	// Acts as the token: counts every transferFrom call it receives and succeeds.
	fallback() external {
		calls++;
	}

	function f(address from, address[] calldata tos, uint[] calldata v) public {
		require(tos.length >= 1);
		require(v.length == tos.length);
		calls = 0;
		bool ok = c.transfer(from, address(this), tos, v);
		assert(ok && calls == tos.length);
	}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address benign, uint amount) public payable {
        require(benign != address(this) && benign.code.length == 0 && amount < 2**128);
        address[] memory tos = new address[](2);
        tos[0] = benign;
        tos[1] = address(this);
        uint[] memory v = new uint[](2);
        v[0] = 0;
        v[1] = amount;
        bool reverted;
        try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    fallback() external { revert(); }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length >= 2);
        require(v.length < _tos.length);
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint calls;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint[] memory v) public {
        require(tos.length > 0 && tos.length == v.length);
        calls = 0;
        bool reverted;
        try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted && calls == tos.length);
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        calls++;
        return "";
    }
    receive() external payable {}
}
